"c4.fig2.leg_seta": {"t": "o comparecimento caiu: a barra divide a perda", "rotulo": 46},
"c4.fig2.aria": "Divisão do saldo do comparecimento entre os dois, por lugar",
"c4.fig2.eixo": {"t": "de cada 100 votos do saldo do comparecimento", "rotulo": 52},
